import sys
import heapq

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(n, edges):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    mst_edges = []
    edges.sort(key=lambda x: x[2])
    for u, v, d in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_edges.append((u, v, d))
    return parent

def bfs(tree, n, u, v):
    queue = [(u, 0)]
    visited = [False] * (n + 1)
    visited[u] = True
    while queue:
        node, dist = queue.pop(0)
        if node == v:
            return dist
        for neighbor, weight in tree[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append((neighbor, dist + weight))
    return float('inf')

